import re

from django.db import migrations, models


ENRICHMENT = re.compile(r"^Labels( and image)? added from (Wikidata .+)$")


def move_enrichment_notes(apps, schema_editor):
    """Enrichment notes the Wikidata importer appended to source_citation
    support labels and images only; move them to field_sources."""
    for model in apps.get_app_config("cidoc_data").get_models():
        names = {f.name for f in model._meta.get_fields()}
        if not {"source_citation", "field_sources"} <= names:
            continue
        for row in model.objects.filter(source_citation__contains="added from Wikidata"):
            kept, sources = [], dict(row.field_sources or {})
            for line in (row.source_citation or "").splitlines():
                m = ENRICHMENT.match(line.strip())
                if not m:
                    kept.append(line)
                    continue
                sources["labels"] = m.group(2)
                if m.group(1):
                    sources["media"] = m.group(2)
            row.source_citation = "\n".join(kept).strip()
            row.field_sources = sources
            row.save(update_fields=["source_citation", "field_sources"])


